  protected show(kind: SnackKind): void {
    const config = {
      success: {
        message: 'Cambios guardados correctamente.',
        action: 'Deshacer',
        duration: 4000,
        panelClass: ['app-snack', 'app-snack-success'],
      },
      info: {
        message: 'Ten\xE9s 3 mensajes nuevos.',
        action: 'Ver',
        duration: 4000,
        panelClass: ['app-snack', 'app-snack-info'],
      },
      error: {
        message: 'No se pudo conectar con el servidor.',
        action: 'Reintentar',
        duration: 6000,
        panelClass: ['app-snack', 'app-snack-error'],
      },
    }[kind];

    const ref = this.snackBar.open(config.message, config.action, {
      duration: config.duration,
      panelClass: config.panelClass,
    });

    ref.onAction().subscribe(() => {
      this.snackBar.open('Acci\xF3n ejecutada: ' + config.action, undefined, { duration: 2500 });
    });
  }
